// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategory/** * NOUS — App Handler (Module 10 v2 — Step 10.7). * * Launches apps by package name or fuzzy display-name match. * * ## Behavior (per strategy §"Apps") * *  - **By package name** (`OpenApp(packageName="com.google.android.youtube")`): *    Direct launch via `PackageManager.getLaunchIntentForPackage`. * *  - **By fuzzy name** (`OpenApp(packageName=null, appName="YouTube")`): *    [AppLauncherService.findPackageByName] finds the best matching *    installed app via [AppNameMatcher] (exact → contains → Levenshtein). * * ## Idempotent execution (Review 2 Elite 1) * * If the target app is already in the foreground, skip the launch (avoids * a duplicate activity stack). [AppLauncherService.isAppInForeground] * currently returns false (Android restricts this since 5.0) — the * idempotent check is best-effort. * * ## Reversibility * * Not reversible — "undo" can't put an app back where it was. Implements * plain [SystemOperationHandler] (not [ReversibleHandler]). * * ## Resource category * * App launches use [ResourceCategory.SETTINGS] (no shared hardware) — * multiple app launches in a batch run in parallel. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Scope — Apps</a> */class AppHandler(    private val appLauncherService: AppLauncherService,) : StatelessSystemOperationHandler<SystemOperation.OpenApp>() {    override val id: String = "app"    override val displayName: String = "App Launcher"    override val requiredPermissions: Set<String> = emptySet()    override val resourceCategory: ResourceCategory = ResourceCategory.SETTINGS    override fun isAvailable(): Boolean = true  // all devices can launch apps    override suspend fun execute(operation: SystemOperation.OpenApp): Result<Unit> {        val packageName = operation.packageName            ?: resolvePackageNameByName(operation.appName)            ?: return Result.Failure(                error = AppError.Hardware.Unsupported(                    resource = "app:${operation.appName ?: "unknown"}",                    cause = null,                ),                correlationId = CorrelationId.generate(),                durationNanos = 0,            ).also {                Timber.tag("AppHandler").w("App not found: ${operation.appName}")            }        // Idempotent: skip if app is already in foreground.        if (appLauncherService.isAppInForeground(packageName)) {            return Result.Success(                data = Unit,                correlationId = CorrelationId.generate(),                durationNanos = 0,                warnings = listOf("idempotent_skip"),            )        }        val launched = appLauncherService.launchByPackage(packageName)        return if (launched) {            Result.Success(Unit, CorrelationId.generate(), 0)        } else {            Result.Failure(                error = AppError.Hardware.Unknown("app:$packageName"),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }    /** Resolve a fuzzy app name to a package name. */    private fun resolvePackageNameByName(appName: String?): String? {        if (appName.isNullOrBlank()) return null        return appLauncherService.findPackageByName(appName)    }}
